def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [a for a, b in history]
    opp = [b for a, b in history]

    opp_d = sum(1 for x in opp if x == 'D')
    my_d = sum(1 for x in my if x == 'D')
    opp_c = n - opp_d

    last_opp = opp[-1]

    after_C = 0
    after_D = 0
    for i in range(n - 1):
        if my[i] == 'D':
            if opp[i + 1] == 'C':
                after_C += 1
            else:
                after_D += 1

    r5 = opp[-5:] if n >= 5 else opp
    r5_d = sum(1 for x in r5 if x == 'D')

    r10 = opp[-10:] if n >= 10 else opp
    r10_d = sum(1 for x in r10 if x == 'D')

    consec_d = 0
    for b in reversed(opp):
        if b == 'D':
            consec_d += 1
        else:
            break

    if opp_d == 0 and n >= 5:
        if my_d == 0:
            return 'D'
        if after_C >= 1:
            return 'D'
        return 'C'

    if n < 10:
        if opp_d >= max(3, n - 2):
            return 'D'
        if last_opp == 'D' and r5_d >= 4:
            return 'D'
        return 'C'

    if n == 98:
        if after_D == 0 and after_C >= 2 and r5_d == 0 and opp_c >= opp_d:
            return 'D'
        if opp_d * 2 > n or r10_d >= 6:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if consec_d >= 6 or (r5_d >= 5 and opp_d * 2 > n):
            return 'D'
        if r10_d >= 8:
            return 'D'
        if opp_d * 2 > n or opp_d >= n - 2:
            return 'D'
        if opp_d >= 6 and r10_d >= 5:
            return 'D'
        return 'C'

    if opp_d * 2 > n or opp_d >= n - 2 or r10_d >= 7:
        return 'D'

    if after_D == 0 and after_C >= 2 and r5_d == 0 and opp_c >= opp_d:
        return 'D'
    if after_D == 0 and after_C >= 2 and r10_d <= 2 and opp_c > opp_d:
        return 'D'

    return 'C'
